SELECT o.order_id, o.order_no, u.username, COUNT(oi.item_id) AS item_count, o.total_price, o.pay_status, o.order_status, o.create_time, o.pay_time FROM tb_order o LEFT JOIN tb_user u ON o.user_id = u.user_id LEFT JOIN tb_order_item oi ON o.order_id = oi.order_id
o.is_deleted = 0
AND (o.order_no LIKE CONCAT('%', #{param.keyword}, '%') OR u.username LIKE CONCAT('%', #{param.keyword}, '%'))
AND o.pay_status = #{param.payStatus}
AND o.order_status = #{param.orderStatus}
AND DATE(o.create_time) >= #{param.startDate}
AND DATE(o.create_time) <= #{param.endDate}
GROUP BY o.order_id ORDER BY o.create_time DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(DISTINCT o.order_id)
FROM tb_order o
LEFT JOIN tb_user u ON o.user_id = u.user_id

    o.is_deleted = 0

        AND (o.order_no LIKE CONCAT('%', #{param.keyword}, '%')
